#include <stdio.h>
#include <string.h>

int add_one(char *s, int len) {
    int i = len - 1;
    while (i >= 0 && s[i] == '9') {
        s[i] = '0';
        i--;
    }
    if (i >= 0) {
        s[i]++;
        return len;
    } else {
        memmove(s + 1, s, len);
        s[0] = '1';
        return len + 1;
    }
}

int main() {
    int N;
    scanf("%d", &N);

    char S[1005];
    for (int i = 0; i < N; i++) {
        int d;
        scanf("%d", &d);
        S[i] = (char)('0' + d);
    }
    S[N] = '\0';

    char cur[1005];

    for (int L = 1; L <= N; L++) {
        if (S[0] == '0') break;

        memcpy(cur, S, L);
        int len = L;
        int pos = L;
        int ok = 1;

        while (pos < N) {
            len = add_one(cur, len);

            if (pos + len > N) {
                ok = 0;
                break;
            }

            for (int j = 0; j < len; j++) {
                if (cur[j] != S[pos + j]) {
                    ok = 0;
                    break;
                }
            }

            if (!ok) break;
            pos += len;
        }

        if (ok && pos == N) {
            printf("%.*s\n", L, S);
            return 0;
        }
    }

    return 0;
}
